"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1251],{92064:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"EventOrchestrator","desc":"Server-authoritative scheduler that decides when in-game events fire. Drives\\na virtual odometer (distance the train has traveled, accumulated only while\\nrunning) and one independent state machine per channel. Each channel rolls a\\nweighted table at a configurable distance cadence; the roll may come up empty\\n(a `Nothing` entry) with a pity guard that forces a real event after enough\\nempty rolls. Events plug in as handler modules implementing EventHandler.\\n\\nAll tuning lives in EventConfig. The orchestrator never touches networking \u2014\\neach handler owns its own client communication.","realm":["Server"],"source":{"line":16,"path":"src/ServerStorage/SharedModules/EventOrchestrator.luau"}}')}}]);